import type { GameObj, Vec2 } from "kaplay"
import { k } from "../../main"
import { tags } from "../../tags"
import { setPerformanceCounter } from "../debug/frameProfilerService"
import type { RunFrameContext } from "../runs/runLoopService"
import { SpatialHash } from "./spatialHash"

const SPATIAL_CELL_SIZE = 96
const LEGACY_POSITION_PADDING = 48
const spatialHash = new SpatialHash<GameObj & { pos: Vec2 }>(SPATIAL_CELL_SIZE)
const projectileSpatialHash = new SpatialHash<GameObj & { pos: Vec2 }>(SPATIAL_CELL_SIZE)
const enemyUnitSpatialHash = new SpatialHash<GameObj & { pos: Vec2 }>(SPATIAL_CELL_SIZE)
const spatialObjects: Array<GameObj & { pos: Vec2 }> = []
const projectileObjects: Array<GameObj & { pos: Vec2 }> = []
const enemyUnitObjects: Array<GameObj & { pos: Vec2 }> = []
const spatialObjectIndices = new Map<number, number>()
let registryInitialized = false
let maxProjectileSweepDistance = 0

const DENSE_INDEX_THRESHOLD = 750

export function updateRuntimeSpatialIndex(context: RunFrameContext) {
	ensureSpatialObjectRegistry()
	if (
		spatialObjects.length >= DENSE_INDEX_THRESHOLD &&
		context.frame % 2 !== 0
	) {
		setPerformanceCounter("spatialIndexSkipped", 1)
		return
	}
	setPerformanceCounter("spatialIndexSkipped", 0)
	rebuildRuntimeSpatialIndex()
}

export interface SpatialQueryOptions {
	allTags?: string[]
	anyTags?: string[]
	excludeIds?: ReadonlySet<number> | readonly number[]
}

export function rebuildRuntimeSpatialIndex() {
	ensureSpatialObjectRegistry()
	projectileObjects.length = 0
	enemyUnitObjects.length = 0
	maxProjectileSweepDistance = 0
	for (let index = 0; index < spatialObjects.length; index++) {
		const obj = spatialObjects[index]
		if (obj.is(tags.projectile)) {
			projectileObjects.push(obj)
			const previousPos = (obj as GameObj & {
				previousPos?: Vec2
			}).previousPos
			if (previousPos) {
				maxProjectileSweepDistance = Math.max(
					maxProjectileSweepDistance,
					previousPos.dist(obj.pos)
				)
			}
		}
		if (obj.is(tags.enemy) && obj.is(tags.unit)) enemyUnitObjects.push(obj)
	}
	spatialHash.rebuild(spatialObjects)
	projectileSpatialHash.rebuild(projectileObjects)
	enemyUnitSpatialHash.rebuild(enemyUnitObjects)
	setPerformanceCounter("spatialObjects", spatialHash.size)
	setPerformanceCounter("spatialCells", spatialHash.activeCellCount)
	setPerformanceCounter("spatialProjectiles", projectileSpatialHash.size)
	setPerformanceCounter("spatialEnemyUnits", enemyUnitSpatialHash.size)
	setPerformanceCounter(
		"projectileSweepDistance",
		Math.ceil(maxProjectileSweepDistance)
	)
}

export function getMaxProjectileSweepDistance() {
	return maxProjectileSweepDistance
}

export function getRuntimeEnemyUnits(): readonly GameObj[] {
	return enemyUnitObjects
}

export function forEachSpatialNearby(
	pos: Vec2,
	radius: number,
	options: SpatialQueryOptions,
	visitor: (obj: GameObj) => boolean | void
) {
	const radiusSquared = radius * radius
	return selectSpatialHash(options).forEachNearby(
		pos,
		radius,
		(obj) => {
			if (!obj.exists() || !obj.pos || isExcluded(obj.id, options.excludeIds)) return
			if (!matchesTags(obj, options)) return
			const dx = obj.pos.x - pos.x
			const dy = obj.pos.y - pos.y
			if (dx * dx + dy * dy > radiusSquared) return
			return visitor(obj)
		},
		LEGACY_POSITION_PADDING
	)
}

function selectSpatialHash(options: SpatialQueryOptions) {
	if (options.allTags?.includes(tags.projectile)) return projectileSpatialHash
	if (
		options.allTags?.includes(tags.enemy) &&
		options.allTags.includes(tags.unit)
	) return enemyUnitSpatialHash
	return spatialHash
}

export function findSpatialNearby(
	pos: Vec2,
	radius: number,
	options: SpatialQueryOptions
) {
	let found: GameObj | undefined
	forEachSpatialNearby(pos, radius, options, (obj) => {
		found = obj
		return false
	})
	return found
}

export function findClosestSpatial(
	pos: Vec2,
	radius: number,
	options: SpatialQueryOptions
) {
	let closest: GameObj | undefined
	let closestDistanceSquared = radius * radius
	forEachSpatialNearby(pos, radius, options, (obj) => {
		const dx = obj.pos.x - pos.x
		const dy = obj.pos.y - pos.y
		const distanceSquared = dx * dx + dy * dy
		if (distanceSquared >= closestDistanceSquared) return
		closest = obj
		closestDistanceSquared = distanceSquared
	})
	return closest
}

export function querySpatialNearby(
	pos: Vec2,
	radius: number,
	options: SpatialQueryOptions
) {
	const results: GameObj[] = []
	forEachSpatialNearby(pos, radius, options, (obj) => results.push(obj))
	return results
}

function matchesTags(obj: GameObj, options: SpatialQueryOptions) {
	if (options.allTags) {
		for (const tag of options.allTags) {
			if (!obj.is(tag)) return false
		}
	}
	if (options.anyTags && options.anyTags.length > 0) {
		let found = false
		for (const tag of options.anyTags) {
			if (!obj.is(tag)) continue
			found = true
			break
		}
		if (!found) return false
	}
	return true
}

function ensureSpatialObjectRegistry() {
	if (registryInitialized) return
	registryInitialized = true
	for (const obj of k.get(tags.gameLoop) as Array<GameObj & { pos: Vec2 }>) {
		registerSpatialObject(obj)
	}
	k.onAdd(tags.gameLoop, (obj) => {
		registerSpatialObject(obj as GameObj & { pos: Vec2 })
	})
}

function registerSpatialObject(obj: GameObj & { pos: Vec2 }) {
	if (spatialObjectIndices.has(obj.id)) return
	spatialObjectIndices.set(obj.id, spatialObjects.length)
	spatialObjects.push(obj)
	obj.onDestroy(() => unregisterSpatialObject(obj.id))
}

function unregisterSpatialObject(id: number) {
	const index = spatialObjectIndices.get(id)
	if (index === undefined) return
	const lastIndex = spatialObjects.length - 1
	const lastObject = spatialObjects[lastIndex]
	if (index !== lastIndex) {
		spatialObjects[index] = lastObject
		spatialObjectIndices.set(lastObject.id, index)
	}
	spatialObjects.pop()
	spatialObjectIndices.delete(id)
}

function isExcluded(
	id: number,
	excluded: ReadonlySet<number> | readonly number[] | undefined
) {
	if (!excluded) return false
	return Array.isArray(excluded)
		? excluded.includes(id)
		: (excluded as ReadonlySet<number>).has(id)
}
