export function clearAllUpgrades() {
	const clearedUpgradeCount = (Object.keys(upgrades) as ToolKey[]).filter(
		(key) => loadout[key] !== undefined || levelLoadout[key] !== undefined
	).length

	setLoadout({})
	setLoadoutRarity({})
	resetLevelLoadout()
	upgradeService.reset()
	return clearedUpgradeCount
}
